const overdue = (days) => (inv) => Date.now() - inv.dueDate > days * 864e5;
const and = (...rules) => (candidate) => rules.every((rule) => rule(candidate));

const collectable = and(
  overdue(30),
  (inv) => inv.noticesSent >= 3,
  (inv) => !inv.inCollection,
);

const toCollect = invoices.filter(collectable);
